27	// Phase 7: rekursive DOM-Helfer — die alten Regexe fanden Tags auf beliebiger Tiefe;
28	// diese Helfer erhalten dieses Verhalten auf dem KF-1-DOM.
29	void collect_named(comdare::common::xml::XmlNode const& node, std::string_view tag,
30	                   std::vector<comdare::common::xml::XmlNode const*>& out) {
31	    for (auto const& c : node.children) {
32	        if (c.tag == tag) out.push_back(&c);
33	        collect_named(c, tag, out);
34	    }
35	}
36	
37	[[nodiscard]] comdare::common::xml::XmlNode const* find_first_named(comdare::common::xml::XmlNode const& node,
38	                                                                    std::string_view                     tag) {
39	    for (auto const& c : node.children) {
40	        if (c.tag == tag) return &c;
41	        if (auto const* hit = find_first_named(c, tag)) return hit;
42	    }
43	    return nullptr;
44	}
