46	// DOM-Fassung des frueheren Regex-Extraktors: <tag id="..."><nested>text</nested></tag>
47	std::vector<PermutationEntry> parse_entries_dom(comdare::common::xml::XmlNode const& root,
48	                                                std::string const&                   tag_name) {
49	    std::vector<comdare::common::xml::XmlNode const*> hits;
50	    if (root.tag == tag_name) hits.push_back(&root);
51	    collect_named(root, tag_name, hits);
52	
53	    std::vector<PermutationEntry> entries;
54	    for (auto const* n : hits) {
55	        if (n->attrs.find("id") == n->attrs.end()) continue; // Regex verlangte id-Attribut
56	        PermutationEntry entry;
57	        entry.id = n->attr("id");
58	        for (auto const& c : n->children)
59	            if (!c.text.empty()) entry.attributes[c.tag] = c.text;
60	        entries.push_back(std::move(entry));
61	    }
62	    return entries;
63	}
