65	// KF-1 (2026-06-02): Helfer fuer den Thesis-Profil-Parser.
66	[[nodiscard]] std::vector<std::string> split_ws(std::string const& s) {
67	    std::vector<std::string> out;
68	    std::size_t              i = 0;
69	    while (i < s.size()) {
70	        while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
71	        std::size_t start = i;
72	        while (i < s.size() && !std::isspace(static_cast<unsigned char>(s[i]))) ++i;
73	        if (i > start) out.push_back(s.substr(start, i - start));
74	    }
75	    return out;
76	}
