78	[[nodiscard]] int to_int(std::string const& s, int def) {
79	    int         v     = def;
80	    auto const* begin = s.data();
81	    auto const* end   = s.data() + s.size();
82	    auto [ptr, ec]    = std::from_chars(begin, end, v);
83	    (void)ptr;
84	    return (ec == std::errc{}) ? v : def;
85	}
