89	CacheEngineConfig XmlConfigParser::parse(std::filesystem::path const& root_dir) const {
90	    CacheEngineConfig cfg;
91	    cfg.cache_engine_permutations     = parse_one(root_dir / "cache_engine_permutations.xml");
92	    cfg.search_algorithm_permutations = parse_one(root_dir / "search_algorithm_permutations.xml");
93	    cfg.allocator_permutations        = parse_one(root_dir / "allocator_permutations.xml");
94	    // GO-5 Fork 2 (R2 ENTSCHIEDEN, 2026-07-12, Dossier A.2): DEPRECATED-Slot. `test_data_sets.xml`
95	    // existiert nirgends (0x) und darf NICHT nachtraeglich erzeugt werden — die WAHRHEITSQUELLE der
96	    // Datensaetze sind die Akten `Code/test_data_xml/*.test_data.xml` (super; #25-Kanon), die der
97	    // E4-Weg ueber `<datasets>` im comdare_thesis_profile referenziert (Fork 1/A.1). Der Aufruf
98	    // bleibt fuer den COMDARE_LEGACY_MESSREIHEN-gated Legacy-Pfad stehen (Doku-nie-loeschen) und
99	    // diagnostiziert die fehlende Datei laut (parse_one, keine stille-{}-Falle).
100	    cfg.test_data_sets = parse_one(root_dir / "test_data_sets.xml");
101	
102	    // REV 7.6 V8.6 — Optional: algorithm_profiles + Messreihen
103	    auto profiles_dir = root_dir / "algorithm_profiles";
104	    if (std::filesystem::is_directory(profiles_dir / "sota")) {
105	        cfg.sota_profiles = load_sota_profiles(profiles_dir / "sota");
106	    }
107	    auto messreihen_xml = root_dir / "messreihen.xml";
108	    if (std::filesystem::exists(messreihen_xml)) { cfg.messreihen = load_messreihen(messreihen_xml); }
109	    return cfg;
110	}
