112	std::vector<PermutationEntry> XmlConfigParser::parse_one(std::filesystem::path const& xml_file) const {
113	    // Phase 7: stille-{}-Falle bereinigt — Rueckgabe bleibt {} (Legacy-4-Datei-Schema ist optional),
114	    // aber NICHT mehr schweigend. GO-5 Fork 2 (2026-07-12): R2 ist ENTSCHIEDEN — test_data_sets.xml
115	    // ist ein DEPRECATED-Slot; Wahrheitsquelle = die Code/test_data_xml/*.test_data.xml-Akten (A.2).
116	    if (!std::filesystem::exists(xml_file)) {
117	        std::cerr << "[xml-config] optionale Datei fehlt: " << xml_file.string()
118	                  << " (Legacy-4-Datei-Schema; test_data_sets.xml = DEPRECATED-Slot, Wahrheitsquelle "
119	                     "sind die Code/test_data_xml/*.test_data.xml-Akten — GO-5 Fork 2/R2)\n";
120	        return {};
121	    }
122	    std::string content = read_file(xml_file);
123	    auto        root    = comdare::common::xml::parse_document(content);
124	    if (root) {
125	        // Probiere verschiedene Tag-Namen aus (Verhalten des frueheren Regex-Pfads)
126	        for (auto const& tag :
127	             {"cache_engine_permutation", "search_algorithm", "allocator_permutation", "test_data_set"}) {
128	            auto entries = parse_entries_dom(*root, tag);
129	            if (!entries.empty()) return entries;
130	        }
131	    }
132	    std::cerr << "[xml-config] WARNUNG: " << xml_file.string()
133	              << " existiert, lieferte aber 0 Eintraege (kein bekannter Permutations-Tag / kein "
134	                 "wohlgeformtes XML)\n";
135	    return {};
136	}
