139	std::vector<AlgorithmProfile> XmlConfigParser::load_sota_profiles(std::filesystem::path const& sota_dir) const {
140	    std::vector<AlgorithmProfile> result;
141	    if (!std::filesystem::is_directory(sota_dir)) return result;
142	    for (auto const& entry : std::filesystem::directory_iterator(sota_dir)) {
143	        auto const& p = entry.path();
144	        if (p.extension() == ".xml" && p.filename().string().find(".profile.") != std::string::npos) {
145	            result.push_back(parse_profile(p));
146	        }
147	    }
148	    return result;
149	}
