151	AlgorithmProfile XmlConfigParser::parse_profile(std::filesystem::path const& profile_xml) const {
152	    AlgorithmProfile prof;
153	    if (!std::filesystem::exists(profile_xml)) return prof;
154	    std::string content = read_file(profile_xml);
155	    auto        root    = comdare::common::xml::parse_document(content);
156	    if (!root) return prof;
157	
158	    // Wurzel <comdare_algorithm_profile id=".." paper_ref=".." pruefling_type="..">
159	    // Review wf_8508f98c (CONFIRMED): KEIN Fallback auf fremde Wurzeln — die alte id-Regex war
160	    // auf comdare_algorithm_profile geankert; id=="" bleibt der Kein-Algorithm-Profil-Sentinel
161	    // (51 committete Nicht-SOTA-Akten wuerden sonst scheinbar gueltige Profile liefern).
162	    comdare::common::xml::XmlNode const* profile_node =
163	        (root->tag == "comdare_algorithm_profile") ? &*root : find_first_named(*root, "comdare_algorithm_profile");
164	    if (profile_node == nullptr) return prof;
165	    prof.id             = profile_node->attr("id");
166	    prof.paper_ref      = profile_node->attr("paper_ref");
167	    prof.pruefling_type = profile_node->attr("pruefling_type");
168	
169	    // Achsen aus dem ERSTEN <axes>-Block (Regex nahm content.find("<axes>"))
170	    if (auto const* axes = find_first_named(*profile_node, "axes")) {
171	        for (auto const& c : axes->children)
172	            if (!c.text.empty()) prof.axes[c.tag] = c.text;
173	    }
174	
175	    // key_value_signature + optionale Overrides: jeweils erste Fundstelle im Dokument.
176	    // BEWUSSTE KORREKTUR (Review wf_8508f98c, dokumentiert + im Regressions-Gate eingefroren):
177	    // der DOM dekodiert XML-Entities (&lt; -> <) — die Regex-Fassung transportierte Escapes
178	    // roh in generierte C++-Kommentare (einzige betroffene Akte: masstree key_types).
179	    if (auto const* kt = find_first_named(*profile_node, "key_types")) prof.key_types = kt->text;
180	    if (auto const* vt = find_first_named(*profile_node, "value_types")) prof.value_types = vt->text;
181	    // V19.1 — expected_workload (optional, ueberschreibt V11.2-Heuristik)
182	    if (auto const* ew = find_first_named(*profile_node, "expected_workload")) prof.expected_workload = ew->text;
183	    // V29.A — allocator_override (optional, ueberschreibt axes/allocator)
184	    if (auto const* ao = find_first_named(*profile_node, "allocator_override")) prof.allocator_override = ao->text;
185	    return prof;
186	}
