188	// Verhaltens-Referenz (Review wf_8508f98c, empirisch): diff-frei zur frueher produktiven
189	// TREIBER-Regex auf allen 165 realen Akten (inkl. config_a/b/c mit Mehrfach-Attributen und
190	// <pruefling><profile>-Refs); die engere alte BIBLIOTHEKS-Regex (id als einziges Attribut,
191	// 0 Reihen fuer config_a/b/c) war nie produktiver Konsument.
192	std::vector<Messreihe> XmlConfigParser::load_messreihen(std::filesystem::path const& messreihen_xml) const {
193	    std::vector<Messreihe> result;
194	    if (!std::filesystem::exists(messreihen_xml)) return result;
195	    std::string content = read_file(messreihen_xml);
196	    auto        root    = comdare::common::xml::parse_document(content);
197	    if (!root) return result;
198	
199	    std::vector<comdare::common::xml::XmlNode const*> reihen;
200	    if (root->tag == "messreihe") reihen.push_back(&*root);
201	    collect_named(*root, "messreihe", reihen);
202	    for (auto const* rn : reihen) {
203	        if (rn->attrs.find("id") == rn->attrs.end()) continue; // Regex verlangte id-Attribut
204	        Messreihe r;
205	        r.id = rn->attr("id");
206	        if (auto const* mo = find_first_named(*rn, "mode")) r.mode = parse_mode(mo->text);
207	        std::vector<comdare::common::xml::XmlNode const*> profs;
208	        collect_named(*rn, "profile", profs);
209	        for (auto const* pn : profs)
210	            if (!pn->text.empty()) r.sota_profile_refs.push_back(pn->text);
211	        result.push_back(std::move(r));
212	    }
213	    return result;
214	}
