216	// KF-1 (2026-06-02): comdare_thesis_profile-Parser ueber den self-contained XML-DOM.
217	std::optional<ThesisProfile> XmlConfigParser::parse_thesis_profile(std::filesystem::path const& xml_file) const {
218	    if (!std::filesystem::exists(xml_file)) return std::nullopt;
219	    std::string content = read_file(xml_file);
220	    auto        root    = comdare::common::xml::parse_document(content);
221	    if (!root || root->tag != "comdare_thesis_profile") return std::nullopt;
222	
223	    ThesisProfile tp;
224	    tp.id             = root->attr("id");
225	    tp.schema_version = to_int(root->attr("schema_version", "0"), 0);
226	
227	    if (auto const* bt = root->child("base_tiers")) {
228	        for (auto const* t : bt->children_named("tier"))
229	            tp.base_tiers.push_back({t->attr("id"), t->attr("profile_ref"), t->attr("paper_ref")});
230	    }
231	    if (auto const* pa = root->child("permute_axes")) {
232	        for (auto const* a : pa->children_named("axis")) {
233	            ThesisAxisSpec ax;
234	            ax.ref = a->attr("ref");
235	            for (auto const* v : a->children_named("value")) ax.values.push_back(v->text);
236	            if (ax.ref == "cacheline") { // per-Organ Cache-Line-Unterachse (KF-3)
237	                ax.per_organ = split_ws(a->attr("per_organ"));
238	                for (auto const* x : a->children_named("line_size")) ax.line_sizes.push_back(x->text);
239	                for (auto const* x : a->children_named("alignment")) ax.alignments.push_back(x->text);
240	                for (auto const* x : a->children_named("sw_prefetch_hint")) ax.sw_prefetch_hints.push_back(x->text);
241	            }
242	            if (ax.ref == "node_width") { // FF2-Unterachse Knoten-Breite in Cache-Lines (C2, Muster KF-3)
243	                for (auto const* x : a->children_named("width_in_lines")) ax.width_in_lines.push_back(x->text);
244	            }
245	            if (ax.ref == "alloc_hw") { // NUMA/Page->allocator-Unterachse (F-B, Muster KF-3/C2)
246	                for (auto const* x : a->children_named("numa_node")) ax.alloc_numa_nodes.push_back(x->text);
247	                for (auto const* x : a->children_named("page")) ax.alloc_pages.push_back(x->text);
248	            }
