252	    if (auto const* cd = root->child("compile_dims")) {
253	        if (auto const* w = cd->child("workloads")) tp.workloads = w->text_tokens();
254	        if (auto const* t = cd->child("telemetry")) {
255	            tp.telemetry_mode   = t->attr("mode");
256	            tp.telemetry_silent = (t->attr("silent") == "true");
257	        }
