259	    if (auto const* rd = root->child("runtime_dynamic")) {
260	        if (auto const* tc = rd->child("thread_count")) tp.thread_counts = tc->text_tokens();
261	        if (auto const* hp = rd->child("hw_prefetcher")) tp.hw_prefetcher = hp->text_tokens();
262	        // Die 4 RC-POD-Felder sind laut SCHEMA uint64-Listen. STRIKT validieren (jedes Token
263	        // vollstaendig numerisch), sonst wuerde parse_u64 spaeter nicht-numerisch still auf 0
264	        // mappen = falsch etikettierte Mess-Zeilen. Ungueltig => Profil unlesbar (nullopt).
265	        auto const parse_u64_list_strict = [](auto const* node, std::vector<std::string>& dst) -> bool {
266	            if (node == nullptr) return true;
267	            std::vector<std::string> toks = node->text_tokens();
268	            for (std::string const& t : toks) {
269	                std::uint64_t v      = 0;
270	                auto const [ptr, ec] = std::from_chars(t.data(), t.data() + t.size(), v, 10);
271	                if (ec != std::errc{} || ptr != t.data() + t.size()) return false;
272	            }
273	            dst = std::move(toks);
274	            return true;
275	        };
276	        if (!parse_u64_list_strict(rd->child("prefetch_distance"), tp.prefetch_distances)) return std::nullopt;
277	        if (!parse_u64_list_strict(rd->child("pool_budget_bytes"), tp.pool_budgets_bytes)) return std::nullopt;
278	        if (!parse_u64_list_strict(rd->child("batch_size"), tp.batch_sizes)) return std::nullopt;
279	        if (!parse_u64_list_strict(rd->child("inline_threshold_bytes"), tp.inline_thresholds_bytes))
280	            return std::nullopt;
281	    }
282	    if (auto const* fc = root->child("fixed_conditions")) tp.fixed_conditions = fc->attrs;
283	    if (auto const* rep = root->child("repetitions")) {
284	        tp.repetitions             = to_int(rep->attr("count", "3"), 3);
285	        tp.repetitions_interpolate = (rep->attr("interpolate", "false") == "true");
286	        tp.repetitions_overlay     = (rep->attr("overlay_in_chart", "true") == "true");
287	    }
288	    if (auto const* ms = root->child("modes")) {
289	        for (auto const* m : ms->children_named("mode")) {
