291	            md.name          = m->attr("name");
292	            md.merge         = m->attr("merge");
293	            md.active_axes   = split_ws(m->attr("active_axes"));
294	            md.pruefling     = m->attr("pruefling");
295	            md.replaces_axes = split_ws(m->attr("replaces_axes"));
296	            tp.modes.push_back(std::move(md));
297	        }
298	    }
299	    if (auto const* sa = root->child("static_axes")) tp.static_axes_from = sa->attr("from");
300	    if (auto const* kv = root->child("key_value_signature")) {
301	        if (auto const* k = kv->child("key_types")) tp.key_types = k->text;
302	        if (auto const* v = kv->child("value_types")) tp.value_types = v->text;
