331	    //    Datensatz-AKTEN-Referenzen (Mess-Input D; Single-Source = die test_data-Akten, Fork 2/R2). ADDITIV —
332	    //    fehlt <datasets>, bleibt die Liste leer (heutiges Verhalten byte-identisch, kein Round-Trip-Einfluss). ──
333	    if (auto const* ds = root->child("datasets")) {
334	        for (auto const* d : ds->children_named("dataset")) {
