364	// INC-D (2026-07-14): comdare_experiment-Parser ueber den self-contained XML-DOM (xml_reader.hpp).
365	// REINE Lese-Schicht: liest ALLE Schema-Elemente (Attribute UND verschachtelte Werte). Fehlertolerant —
366	// fehlende optionale Elemente -> Default (leer/false); struktureller Fehler (nicht wohlgeformt / falsches
367	// Wurzel-Tag) -> nullopt. KEINE Enum-/Registry-Aufloesung hier (Baseline-Layering; die lebt in der
368	// cache_engine-Schicht validate_experiment_profile).
369	std::optional<ExperimentProfile>
370	XmlConfigParser::parse_experiment_profile(std::filesystem::path const& xml_file) const {
371	    if (!std::filesystem::exists(xml_file)) return std::nullopt;
372	    std::string content = read_file(xml_file);
373	    auto        root    = comdare::common::xml::parse_document(content);
374	    if (!root || root->tag != "comdare_experiment") return std::nullopt;
375	
376	    ExperimentProfile ep;
377	    ep.version = root->attr("version");
378	    ep.id      = root->attr("id");
379	
380	    if (auto const* md = root->child("metadata")) {
381	        if (auto const* n = md->child("name")) ep.metadata.name = n->text;
382	        if (auto const* m = md->child("mode")) ep.metadata.mode = m->text;
383	    }
384	    if (auto const* ee = root->child("execution_engines")) {
385	        for (auto const* e : ee->children_named("engine"))
386	            ep.engines.push_back({e->attr("id"), e->attr("type"), e->attr("registry")});
387	    }
388	    if (auto const* lw = root->child("lebewesen")) {
389	        for (auto const* t : lw->children_named("tier")) ep.lebewesen.push_back(t->attr("id"));
390	    }
391	    if (auto const* ph = root->child("phases")) {
392	        for (auto const* p : ph->children_named("phase")) {
393	            ExperimentPhase phase;
394	            phase.name      = p->attr("name");
395	            phase.merge     = p->attr("merge");
396	            phase.engine    = p->attr("engine");
397	            phase.engines   = split_ws(p->attr("engines")); // Whitespace-Liste (leer bei Einzel-engine)
398	            phase.pruefling = p->attr("pruefling");
399	            ep.phases.push_back(std::move(phase));
400	        }
401	    }
402	    if (auto const* adl = root->child("axes_default_lookup")) {
403	        ep.axes_default_lookup_enabled = (adl->attr("enabled") == "true" || adl->attr("enabled") == "1");
404	        for (auto const* a : adl->children_named("axis")) {
405	            ExperimentAxisDefault ax;
406	            ax.ref              = a->attr("ref");
407	            ax.allowed_variants = split_ws(a->attr("allowed_variants"));
408	            ep.axes_default_lookup.push_back(std::move(ax));
409	        }
410	    }
411	    if (auto const* w = root->child("workloads")) ep.workloads = w->text_tokens();
412	    if (auto const* ds = root->child("datasets")) {
413	        for (auto const* d : ds->children_named("dataset"))
414	            ep.datasets.push_back({d->attr("id"), d->attr("akte_ref"), d->attr("loader")});
415	    }
416	    if (auto const* mc = root->child("measurement_categories")) {
417	        for (auto const* c : mc->children_named("category")) ep.measurement_categories.push_back(c->attr("name"));
418	    }
419	    if (auto const* ot = root->child("op_types")) ep.op_types = ot->text_tokens();
420	    if (auto const* out = root->child("output")) {
421	        if (auto const* b = out->child("binary_path")) ep.output.binary_path = b->text;
422	        if (auto const* c = out->child("csv_path")) ep.output.csv_path = c->text;
423	        if (auto const* l = out->child("latex_path")) ep.output.latex_path = l->text;
424	        if (auto const* cm = out->child("comparison_metrics"))
425	            ep.output.comparison_metrics = (cm->text == "true" || cm->text == "1");
426	    }
427	    return ep;
428	}
