124	/// validate_profile — DIE reine Pruef-Logik (read-only). `registry` = axis-Name → gueltige Werte (aus den
125	/// EnabledStrategies, vom Host via axis_registry_from_levels(build_all_axis_levels()) hereingereicht).
126	/// `known_workload_ids` = die REAL vorhandenen load_profiles/-ids (aus wd::discover_load_profiles), vom Host
127	/// hereingereicht; leer = die <workloads>-Pruefung (6) wird uebersprungen (rueckwaerts-kompatibel). Prueft
128	/// (1) Achsen-Namen (2) Achsen-Werte (3) axis_sweep- + sota_series-Referenzen (4) fairness (5) datasets
129	/// (6) <workloads>-ids. Schreibt KEINE Datei, baut KEINE DLL, misst NICHTS. Gibt das Ergebnis-POD zurueck;
130	/// der Caller (Host) druckt + mappt auf den Exit-Code.
131	[[nodiscard]] inline ProfileValidationResult validate_profile(cx::ThesisProfile const&     tp,
132	                                                              ex::AxisRegistry const&      registry,
133	                                                              std::set<std::string> const& known_workload_ids = {}) {
134	    ProfileValidationResult r;
135	
136	    // Menge der bekannten Achsen-Namen: Registry-Keys (EnabledStrategies) ∪ kCompositionAxisNames (die 19 Slots).
137	    std::set<std::string> known_axes;
138	    for (auto const& [axis, _] : registry) known_axes.insert(axis);
139	    for (auto const& a : ex::kCompositionAxisNames) known_axes.insert(std::string{a});
140	
141	    // ── (1)+(2): jede <axis ref> bekannt + jeder <value> gueltig. ──
142	    for (auto const& ax : tp.permute_axes) {
143	        ++r.axes_checked;
144	        if (ax.ref == "cacheline") { // KF-3-Sonderzweig (compile-time Cache-Line-Unterachse) — separat.
145	            r.warnings.push_back("axis ref=\"cacheline\": KF-3-Sonderzweig (Cache-Line-Unterachse), "
146	                                 "Werte (line_size/alignment/sw_hint) nicht gegen die Achsen-Registry geprueft.");
147	            continue;
148	        }
149	        if (ax.ref == "node_width") { // C2/FF2-Sonderzweig (compile-time Knoten-Breite in Cache-Lines) — separat.
150	            r.warnings.push_back("axis ref=\"node_width\": C2/FF2-Sonderzweig (Knoten-Breiten-Unterachse), "
151	                                 "Werte (width_in_lines) nicht gegen die Achsen-Registry geprueft.");
152	            continue;
153	        }
154	        if (ax.ref == "alloc_hw") { // F-B-Sonderzweig (compile-time NUMA/Page->allocator) — separat.
155	            r.warnings.push_back("axis ref=\"alloc_hw\": F-B-Sonderzweig (NUMA/Page-Unterachse), "
156	                                 "Werte (numa_node/page) nicht gegen die Achsen-Registry geprueft.");
157	            continue;
158	        }
159	        // (1) Achsen-Name bekannt?
160	        if (known_axes.find(ax.ref) == known_axes.end()) {
161	            r.ok = false;
162	            r.errors.push_back("UNBEKANNTE Achse <axis ref=\"" + ax.ref +
163	                               "\">: kein Achsen-Name der Registry/"
164	                               "EnabledStrategies. Gueltige Achsen = " +
165	                               preview_values([&] {
166	                                   std::vector<std::string> a(known_axes.begin(), known_axes.end());
167	                                   return a;
168	                               }()));
169	            continue; // ohne bekannte Achse koennen die Werte nicht geprueft werden
170	        }
171	        // (2) Achsen-Werte gueltig? Gueltige Werte aus der Registry dieser Achse.
172	        auto it = registry.find(ax.ref);
173	        if (it == registry.end()) {
174	            // Achse ist ein bekannter Slot (kCompositionAxisNames), aber NICHT in der hereingereichten Registry
175	            // (z.B. Host reichte nur eine Teilmenge). Nicht-fatal: Werte koennen nicht geprueft werden.
176	            r.warnings.push_back("axis ref=\"" + ax.ref +
177	                                 "\": bekannter Slot, aber keine Werteliste in der "
178	                                 "hereingereichten Registry — <value>-Pruefung uebersprungen.");
179	            continue;
180	        }
181	        std::vector<std::string> const& valid = it->second;
182	        if (ax.values.empty()) {
183	            // Leere <value>-Liste = build_axis_levels expandiert die volle Registry-Liste (legitim) → nur Hinweis.
184	            r.warnings.push_back("axis ref=\"" + ax.ref + "\": keine <value> — die volle Registry-Liste (" +
185	                                 std::to_string(valid.size()) + " Werte) wird expandiert.");
186	            continue;
187	        }
188	        for (auto const& v : ax.values) {
189	            ++r.values_checked;
190	            if (std::find(valid.begin(), valid.end(), v) == valid.end()) {
191	                r.ok = false;
192	                r.errors.push_back("UNGUELTIGER Wert <axis ref=\"" + ax.ref + "\"><value>" + v +
193	                                   "</value>: kein "
194	                                   "name() der EnabledStrategies dieser Achse. Gueltige Werte = " +
195	                                   preview_values(valid));
196	            }
197	        }
198	    }
199	
200	    // ── Menge der im Profil DEKLARIERTEN Achsen (fuer axis_sweep-Referenz-Pruefung). ──
201	    std::set<std::string> declared_axes;
202	    for (auto const& ax : tp.permute_axes) declared_axes.insert(ax.ref);
203	
204	    // ── (3a): jeder <axis_sweep axis="X"> referenziert eine deklarierte (bzw. bekannte) Achse. ──
205	    for (auto const& sw : tp.axis_sweeps) {
206	        ++r.sweeps_checked;
207	        bool const is_declared = declared_axes.find(sw.axis) != declared_axes.end();
208	        bool const is_known    = known_axes.find(sw.axis) != known_axes.end();
209	        if (!is_declared && !is_known) {
210	            r.ok = false;
211	            r.errors.push_back("UNBEKANNTE Sweep-Achse <axis_sweep axis=\"" + sw.axis +
212	                               "\">: weder im Profil "
213	                               "<permute_axes> deklariert noch ein bekannter Achsen-Name der Registry.");
214	        } else if (!is_declared) {
215	            r.warnings.push_back("axis_sweep axis=\"" + sw.axis +
216	                                 "\": bekannte Achse, aber NICHT in "
217	                                 "<permute_axes> deklariert (Sweep nutzt die Baseline/eigene Sweep-View).");
218	        }
219	    }
220	
221	    // ── Menge der deklarierten base_tier-ids (fuer sota_series-lebewesen-Pruefung). ──
222	    std::set<std::string> tier_ids;
223	    for (auto const& t : tp.base_tiers) tier_ids.insert(t.id);
224	
225	    // ── (3b): jede <sota_series lebewesen="L"> referenziert ein deklariertes <base_tier id="L">.
226	    //    (4) GO-5 Fork 6: fairness (falls gesetzt) ∈ kFairnessModes; fairness-Varianten desselben
227	    //    (lebewesen,merge)-Paars sind bis zur DATEN-gated Kompositions-Pinnung binary_id-GLEICH → WARNUNG. ──
228	    std::map<std::string, std::string> fairness_by_pair; // "lebewesen|merge" → erster fairness-Wert
229	    for (auto const& ss : tp.sota_series) {
230	        ++r.series_checked;
231	        if (tier_ids.find(ss.lebewesen) == tier_ids.end()) {
232	            r.ok = false;
233	            std::vector<std::string> ids(tier_ids.begin(), tier_ids.end());
234	            r.errors.push_back("UNBEKANNTES Lebewesen <sota_series id=\"" + ss.id + "\" lebewesen=\"" + ss.lebewesen +
235	                               "\">: kein deklariertes <base_tier>. Deklarierte base_tiers = " + preview_values(ids));
236	        }
237	        if (!ss.fairness.empty()) {
238	            bool known = false;
239	            for (char const* m : kFairnessModes) known = known || (ss.fairness == m);
240	            if (!known) {
241	                r.ok = false;
242	                r.errors.push_back("UNGUELTIGER Fairness-Modus <sota_series id=\"" + ss.id + "\" lebewesen=\"" +
243	                                   ss.lebewesen + "\" fairness=\"" + ss.fairness +
244	                                   "\">: erlaubt sind common_denominator|native (Thesis §sec:fairness) oder "
245	                                   "weglassen (ungesetzt).");
246	            }
247	        }
248	        auto const [it, inserted] = fairness_by_pair.emplace(ss.lebewesen + "|" + ss.merge, ss.fairness);
249	        if (!inserted && it->second != ss.fairness) {
250	            r.warnings.push_back(
251	                "sota_series lebewesen=\"" + ss.lebewesen + "\" merge=\"" + ss.merge +
252	                "\": mehrere fairness-Varianten desselben (lebewesen,merge)-Paars erzeugen bis zur "
253	                "DATEN-gated Kompositions-Pinnung (GO-5 Fork 6) DIESELBE binary_id/DLL — die Paesse "
254	                "teilen sich ein per-Binary-Verzeichnis (Resume unterscheidet sie nur ueber den Stamp).");
255	        }
256	    }
257	
258	    // ── (5) GO-5 Fork 1: <datasets>-FORMAT-Checks (Datei-Existenz ist super-seitig — hier bewusst NICHT). ──
259	    std::set<std::string> seen_dataset_ids;
260	    for (auto const& d : tp.datasets) {
261	        ++r.datasets_checked;
262	        if (d.id.empty()) {
263	            r.ok = false;
264	            r.errors.push_back("DATASET ohne id: <dataset akte_ref=\"" + d.akte_ref +
265	                               "\"> braucht einen eindeutigen Kurznamen (id).");
266	        } else if (!seen_dataset_ids.insert(d.id).second) {
267	            r.ok = false;
268	            r.errors.push_back("DOPPELTE Dataset-id <dataset id=\"" + d.id +
269	                               "\">: die id muss je Profil eindeutig sein (Referenz-Schluessel).");
270	        }
271	        static constexpr std::string_view kAkteSuffix = ".test_data.xml";
272	        bool const                        suffix_ok =
273	            d.akte_ref.size() > kAkteSuffix.size() &&
274	            d.akte_ref.compare(d.akte_ref.size() - kAkteSuffix.size(), kAkteSuffix.size(), kAkteSuffix) == 0;
275	        if (!suffix_ok) {
276	            r.ok = false;
277	            r.errors.push_back("UNGUELTIGE Akten-Referenz <dataset id=\"" + d.id + "\" akte_ref=\"" + d.akte_ref +
278	                               "\">: muss auf eine test_data-AKTE (…<name>.test_data.xml) zeigen — die Akten "
279	                               "sind die Single-Source (GO-5 Fork 2/R2; Datei-Existenz prueft die super-Seite).");
280	        }
281	        if (d.loader.empty()) {
282	            r.ok = false;
283	            r.errors.push_back("DATASET ohne loader: <dataset id=\"" + d.id +
284	                               "\"> braucht eine DatasetLoaderRegistry-loader_id (z.B. string_corpus).");
285	        } else {
286	            bool known = false;
287	            for (char const* l : kKnownDatasetLoaderIds) known = known || (d.loader == l);
288	            if (!known) {
289	                r.warnings.push_back("dataset id=\"" + d.id + "\" loader=\"" + d.loader +
290	                                     "\": keine Repo-Loader-id (string_corpus|sosd_uint64). Die Registry ist "
291	                                     "laufzeit-offen, ABER ein Tippfehler fiele beim Mess-Konsum still auf den "
292	                                     "YCSB-Generator zurueck (load_or_generate_ycsb-Fallback).");
293	            }
294	        }
295	    }
296	
297	    // ── (7) INC-3 Familie A: <measurement_categories>-Namen-Check. SINGLE-SOURCE der gueltigen Namen =
298	    //    kMeasurementAxisRegistry (die 16 System-Kategorien, measurement_axis_registry.hpp) — NICHT hartkodiert.
299	    //    Kategorien sind eine Spalten-PROJEKTION, keine Achse → binary_id-neutral. Unbekannter Name = HARTER
300	    //    Fehler (sonst stille leere/falsche Projektion); mehrfache Nennung = WARNUNG (redundante Spalte). ──
301	    if (!tp.measurement_categories.empty()) {
302	        std::set<std::string> valid_categories;
303	        for (auto const& info : ms::kMeasurementAxisRegistry) valid_categories.insert(std::string{info.name});
304	        std::set<std::string> seen_categories;
305	        for (auto const& cat : tp.measurement_categories) {
306	            ++r.categories_checked;
307	            if (valid_categories.find(cat) == valid_categories.end()) {
308	                r.ok = false;
309	                std::vector<std::string> const valid(valid_categories.begin(), valid_categories.end());
310	                r.errors.push_back("UNGUELTIGE Mess-Kategorie <measurement_categories><category name=\"" + cat +
311	                                   "\">: kein MeasurementCategory-Name (Single-Source kMeasurementAxisRegistry, "
312	                                   "die 16 System-Kategorien). Gueltige Kategorien = " +
313	                                   preview_values(valid));
314	            } else if (!seen_categories.insert(cat).second) {
315	                r.warnings.push_back("category name=\"" + cat +
316	                                     "\": mehrfach deklariert — redundante Spalten-Projektion (nicht fatal).");
317	            }
318	        }
319	    }
320	
321	    // ── (6) M-CE-12: jede <workloads>-id ist eine REAL existente load_profiles/-id. Nur wenn der Host die
322	    //    entdeckten ids hereinreicht (known_workload_ids nicht leer) — leer = Pruefung uebersprungen
323	    //    (rueckwaerts-kompatibel: 2-arg-Aufrufer/Tests ohne Host-Enumeration). Leere <workloads> im Profil =
324	    //    "alle Lastprofile" (legitim) → nichts zu pruefen. Eine unbekannte id ist ein HARTER Fehler: sie matcht
325	    //    0 Lastprofile, wodurch der spaetere E4-Lauf mit exit 4 abbricht (Achse 2 darf nicht still entfallen). ──
326	    if (!known_workload_ids.empty()) {
327	        std::vector<std::string> const valid_wl(known_workload_ids.begin(), known_workload_ids.end());
328	        for (auto const& w : tp.workloads) {
329	            ++r.workloads_checked;
330	            if (known_workload_ids.find(w) == known_workload_ids.end()) {
331	                r.ok = false;
332	                r.errors.push_back("UNBEKANNTE Workload-id <workloads>… " + w +
333	                                   " …</workloads>: keine load_profiles/-id. Die <workloads>-Auswahl ist die "
334	                                   "AUTORITATIVE Achse-2-Auswahl; eine unbekannte id matcht 0 Lastprofile → der "
335	                                   "E4-Lauf braeche mit exit 4 ab (Achse 2 darf nicht still entfallen). "
336	                                   "Gueltige ids = " +
337	                                   preview_values(valid_wl));
338	            }
339	        }
340	    }
341	
342	    return r;
343	}
