345	/// print_validation_report — druckt das Ergebnis menschenlesbar (Host nutzt es; der Test prueft die Literale).
346	inline void print_validation_report(ProfileValidationResult const& r, cx::ThesisProfile const& tp, std::ostream& os) {
347	    os << "=== PROFIL-VALIDAT (rein-lesend; KEIN DLL-Bau, KEINE Messung) ===\n";
348	    os << "  Profil id=" << tp.id << " schema_version=" << tp.schema_version << "\n";
349	    os << "  geprueft: " << r.axes_checked << " Achsen, " << r.values_checked << " Werte, " << r.sweeps_checked
350	       << " axis_sweeps, " << r.series_checked << " sota_series";
351	    // M-CE-12: workloads NUR ausgeben, wenn geprueft (Host reichte known_workload_ids herein) — die --validate-
352	    // Ausgabe der 2-arg-Aufrufer (Tests ohne Host-Enumeration) bleibt byte-identisch.
353	    if (r.workloads_checked > 0) os << ", " << r.workloads_checked << " workloads";
354	    // GO-5 Fork 1: datasets NUR ausgeben, wenn deklariert — die --validate-Ausgabe bestehender Profile
355	    // (ohne <datasets>) bleibt byte-identisch (Default-Verhaltens-Gate dieses Increments).
356	    if (r.datasets_checked > 0) os << ", " << r.datasets_checked << " datasets";
357	    // INC-3 Familie A: measurement_categories NUR ausgeben, wenn deklariert — die --validate-Ausgabe
358	    // bestehender Profile (ohne <measurement_categories>) bleibt byte-identisch (Default-Verhaltens-Gate).
359	    if (r.categories_checked > 0) os << ", " << r.categories_checked << " measurement_categories";
360	    os << "\n";
361	    for (auto const& w : r.warnings) os << "  [HINWEIS] " << w << "\n";
362	    for (auto const& e : r.errors) os << "  [FEHLER]  " << e << "\n";
363	    if (r.ok)
364	        os << "VALIDAT OK: das Profil ist gegen die AxisRegistry/EnabledStrategies konsistent.\n";
365	    else
366	        os << "VALIDAT FEHLGESCHLAGEN: " << r.errors.size() << " Fehler — Profil NICHT baubar (Abbruch vor Bau).\n";
367	}
