370	// INC-D (2026-07-14): validate_experiment_profile — das REIN-LESENDE Validat des comdare_experiment-
371	// Profils (ExperimentProfile, common-Schicht) gegen die cache_engine-Wahrheiten. Muster = validate_profile
372	// (Specification/Validator; read-only). Die common-Schicht traegt NUR Strings; DIESE cache_engine-Schicht
373	// loest sie gegen die MergeStrategy-Enum + die Registry-XML + kAllMeasurementCategories auf (Baseline-
374	// Layering: common referenziert NIE cache_engine).
375	//
376	// PRUEFUNGEN:
377	//   (1) GENAU 2 <execution_engines><engine> (ee_ce + ee_prt).
378	//   (2) mindestens 1 <phases><phase>.
379	//   (3) jede phase.merge ∈ MergeStrategy-Enum (pruefling_merge.hpp: Stufe1_CeOnly/Stufe2_.../Stufe3_...).
380	//   (4) die je-engine referenzierten Registry-Dateien existieren (registry_dir/<registry>).
381	//   (5) jede <axes_default_lookup> allowed_variants ⊆ der `baustein name`-Werte der ce-Registry
382	//       (Wurzel engine="cache_engine") fuer die Achse `ref`; unbekannte Achse = Fehler.
383	//   (6) jede <measurement_categories> category ∈ kAllMeasurementCategories (16, measurement_category.hpp) —
384	//       Single-Source ueber measurement_axis_registry::axis_info(cat).name; Duplikat = WARNUNG.
385	// registry_dir leer = (4)+(5) uebersprungen (rein strukturelle Validierung; der Host reicht das
386	// Registry-Verzeichnis herein — analog validate_profile::known_workload_ids).
387	// ─────────────────────────────────────────────────────────────────────────────
388	
389	namespace pm = ::comdare::cache_engine::anatomy::pruefling;
390	
391	// Die 3 gueltigen MergeStrategy-Enum-Werte (Single-Source = das Enum selbst).
392	inline constexpr pm::MergeStrategy kExperimentMergeStrategies[] = {
393	    pm::MergeStrategy::Stufe1_CeOnly, pm::MergeStrategy::Stufe2_PrueflingReplace, pm::MergeStrategy::Stufe3_FullJoin};
394	
395	// merge_strategy_name — Enum -> kanonischer XML-String. switch OHNE default: -Wswitch faengt Enum-Drift
396	// (eine 4. Stufe muss hier + im XSD nachgezogen werden), statt still eine gueltige Stufe zu verwerfen.
397	[[nodiscard]] inline std::string_view merge_strategy_name(pm::MergeStrategy s) {
398	    switch (s) {
399	        case pm::MergeStrategy::Stufe1_CeOnly: return "Stufe1_CeOnly";
400	        case pm::MergeStrategy::Stufe2_PrueflingReplace: return "Stufe2_PrueflingReplace";
401	        case pm::MergeStrategy::Stufe3_FullJoin: return "Stufe3_FullJoin";
402	    }
403	    return "";
404	}
