42	// ── Die GEWICHTE der cppcheck-Severity-Klassen (Dossier A.7: „Warnungs-Klassen gewichtet"). ──
43	// Single-Source: Generator UND Akte (weights-Attribut) UND Tests speisen sich hier. Konvention:
44	// error dominiert (3x), warning 2x, performance/portability je 1x, style 0.5x — dokumentiert,
45	// deterministisch, in der Akte selbst festgeschrieben (aendern ⇒ Akte neu generieren, nie Hand-Edit).
46	inline constexpr double kH2WeightError       = 3.0;
47	inline constexpr double kH2WeightWarning     = 2.0;
48	inline constexpr double kH2WeightPerformance = 1.0;
49	inline constexpr double kH2WeightPortability = 1.0;
50	inline constexpr double kH2WeightStyle       = 0.5;
51	
52	/// Die Gewichts-Signatur, wie sie WOERTLICH im weights-Attribut der Akte steht (Single-Source-Abgleich).
53	[[nodiscard]] inline std::string h2_weights_signature() {
54	    auto one = [](char const* name, double w) {
55	        char buf[48];
56	        // %g: "3" statt "3.000000" — kompakt + eindeutig fuer die hier verwendeten Konstanten.
57	        int const n = std::snprintf(buf, sizeof(buf), "%s=%g", name, w);
58	        return std::string(buf, (n > 0) ? static_cast<std::size_t>(n) : 0);
59	    };
60	    return one("error", kH2WeightError) + ";" + one("warning", kH2WeightWarning) + ";" +
61	           one("performance", kH2WeightPerformance) + ";" + one("portability", kH2WeightPortability) + ";" +
62	           one("style", kH2WeightStyle);
63	}
64	
65	// ── Die Befund-Zaehler EINER SOTA-Quelle (cppcheck-Severity-Klassen des gefahrenen Enable-Sets). ──
66	struct H2FindingCounts {
67	    std::uint64_t error       = 0;
68	    std::uint64_t warning     = 0;
69	    std::uint64_t style       = 0;
70	    std::uint64_t performance = 0;
71	    std::uint64_t portability = 0;
72	};
73	
74	/// compute_h2_score — DIE Score-Formel: gewichtete Befunde pro kLOC, "%.3f"-formatiert.
75	/// loc==0 ⇒ "n/a" (ehrlich, kein Div-0-Phantom; eine leere Quelle traegt keinen Score).
76	[[nodiscard]] inline std::string compute_h2_score(H2FindingCounts const& f, std::uint64_t loc) {
77	    if (loc == 0) return "n/a";
78	    double const weighted =
79	        kH2WeightError * static_cast<double>(f.error) + kH2WeightWarning * static_cast<double>(f.warning) +
80	        kH2WeightPerformance * static_cast<double>(f.performance) +
81	        kH2WeightPortability * static_cast<double>(f.portability) + kH2WeightStyle * static_cast<double>(f.style);
82	    double const per_kloc = weighted / (static_cast<double>(loc) / 1000.0);
83	    char         buf[64];
84	    int const    n = std::snprintf(buf, sizeof(buf), "%.3f", per_kloc);
85	    return std::string(buf, (n > 0) ? static_cast<std::size_t>(n) : 0);
86	}
