88	// ── EIN Akten-Eintrag = EIN sota/*.profile.xml (Dossier A.7: „je sota/*.profile.xml"). ──
89	struct H2CodeQualityEntry {
90	    std::string     profile_id; // Dateistamm des sota-Profils (== <sota_series lebewesen=..> fuer die 6 SOTA)
91	    std::string     paper_ref;  // paper_ref-Attribut des Profils (P01..P33)
92	    std::string     source;     // vendorte Original-Quelle relativ zur ce-Wurzel (leer bei n/a)
93	    std::string     method;     // "cppcheck_weighted_finding_density_per_kloc"
94	    std::string     computed;   // IMMER "tool" (Anti-Fake: es gibt keinen Hand-Wert-Pfad)
95	    std::string     score;      // "%.3f"-Dichte ODER "n/a" (Rekonstruktion ohne vendorte Quelle)
96	    std::string     reason;     // nur bei score=="n/a": z.B. "no_vendored_original_source"
97	    H2FindingCounts findings{};
98	    std::uint64_t   loc   = 0; // analysierte Zeilen (loc_metric der Akte, physical_lines)
99	    std::uint64_t   files = 0; // analysierte Dateien
100	};
101	
102	// ── Die ganze Akte (Kopf = Tool-Provenienz, FF4; Eintraege in deterministischer profile_id-Reihenfolge). ──
103	struct H2ScoreAkte {
104	    int                             schema_version = 1;
105	    std::string                     tool;         // "cppcheck"
106	    std::string                     tool_version; // z.B. "2.21.0" (aus `cppcheck --version`)
107	    std::string                     tool_args;    // die gepinnten Analyse-Argumente WOERTLICH
108	    std::string                     loc_metric;   // "physical_lines"
109	    std::string                     weights;      // h2_weights_signature()
110	    std::string                     exclude_dirs; // beim Datei-Sammeln uebersprungene Verzeichnisnamen
111	    std::vector<H2CodeQualityEntry> entries;
112	
113	    [[nodiscard]] H2CodeQualityEntry const* entry(std::string_view profile_id) const {
114	        for (auto const& e : entries)
115	            if (e.profile_id == profile_id) return &e;
116	        return nullptr;
117	    }
118	};
