120	/// serialize_h2_score_akte — deterministische XML-Form der Akte (Generator-Output; byte-stabil bei
121	/// identischen Quellen+Tool — bewusst OHNE Zeitstempel, Reproduzierbarkeit vor Protokollierung).
122	[[nodiscard]] inline std::string serialize_h2_score_akte(H2ScoreAkte const& a) {
123	    std::ostringstream os;
124	    os << "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n";
125	    os << "<!-- AUTO-GENERATED by apps/h2_score_akte_tool (GO-5 Fork 7) - DO NOT HAND-EDIT.\n"
126	          "     TOOL-BERECHNETE H2-Code-Qualitaets-Akte (Dossier 20260712-go5 A.7 Option (b)):\n"
127	          "     gewichtete cppcheck-Befunddichte pro kLOC ueber die vendorten ext/-Paper-Quellen.\n"
128	          "     score=\"n/a\" = Rekonstruktion ohne vendorte Original-Quelle (ehrlich, kein Pseudo-Wert).\n"
129	          "     Regenerieren: comdare-h2-score-akte --ce-root <ce> [--cppcheck <exe>] -->\n";
130	    os << "<comdare_h2_quality_akte schema_version=\"" << a.schema_version << "\" tool=\"" << a.tool
131	       << "\" tool_version=\"" << a.tool_version << "\"\n    tool_args=\"" << a.tool_args << "\"\n    loc_metric=\""
132	       << a.loc_metric << "\" weights=\"" << a.weights << "\" exclude_dirs=\"" << a.exclude_dirs << "\">\n";
133	    for (auto const& e : a.entries) {
134	        os << "  <code_quality profile=\"" << e.profile_id << "\" paper_ref=\"" << e.paper_ref << "\" method=\""
135	           << e.method << "\" computed=\"" << e.computed << "\"\n      score=\"" << e.score << "\"";
136	        if (e.score == "n/a") {
137	            os << " reason=\"" << e.reason << "\"/>\n";
138	        } else {
139	            os << " source=\"" << e.source << "\" loc=\"" << e.loc << "\" files=\"" << e.files
140	               << "\"\n      findings_error=\"" << e.findings.error << "\" findings_warning=\"" << e.findings.warning
141	               << "\" findings_style=\"" << e.findings.style << "\" findings_performance=\"" << e.findings.performance
142	               << "\" findings_portability=\"" << e.findings.portability << "\"/>\n";
143	        }
144	    }
145	    os << "</comdare_h2_quality_akte>\n";
146	    return os.str();
147	}
