150	[[nodiscard]] inline std::uint64_t attr_u64(cxml::XmlNode const& n, std::string_view key) noexcept {
151	    try {
152	        std::string const v = n.attr(key);
153	        return v.empty() ? 0u : static_cast<std::uint64_t>(std::stoull(v));
