158	/// parse_h2_score_akte — liest die Akte rein-lesend. nullopt bei fehlender Datei/falschem Wurzel-Tag
159	/// (der Konsument macht daraus honest-n/a, KEIN Abbruch — die Akte ist Metadaten, kein Mess-Gate).
160	[[nodiscard]] inline std::optional<H2ScoreAkte> parse_h2_score_akte(std::filesystem::path const& path) {
161	    std::ifstream in{path, std::ios::binary};
162	    if (!in) return std::nullopt;
163	    std::ostringstream ss;
164	    ss << in.rdbuf();
165	    auto root = cxml::parse_document(ss.str());
166	    if (!root.has_value() || root->tag != "comdare_h2_quality_akte") return std::nullopt;
167	
168	    H2ScoreAkte a;
169	    try {
170	        a.schema_version = std::stoi(root->attr("schema_version", "1"));
171	    } catch (...) { a.schema_version = 1; }
172	    a.tool         = root->attr("tool");
173	    a.tool_version = root->attr("tool_version");
174	    a.tool_args    = root->attr("tool_args");
175	    a.loc_metric   = root->attr("loc_metric");
176	    a.weights      = root->attr("weights");
177	    a.exclude_dirs = root->attr("exclude_dirs");
178	    for (auto const* c : root->children_named("code_quality")) {
179	        H2CodeQualityEntry e;
180	        e.profile_id           = c->attr("profile");
181	        e.paper_ref            = c->attr("paper_ref");
182	        e.source               = c->attr("source");
183	        e.method               = c->attr("method");
184	        e.computed             = c->attr("computed");
185	        e.score                = c->attr("score");
186	        e.reason               = c->attr("reason");
187	        e.loc                  = h2_detail::attr_u64(*c, "loc");
188	        e.files                = h2_detail::attr_u64(*c, "files");
189	        e.findings.error       = h2_detail::attr_u64(*c, "findings_error");
190	        e.findings.warning     = h2_detail::attr_u64(*c, "findings_warning");
191	        e.findings.style       = h2_detail::attr_u64(*c, "findings_style");
192	        e.findings.performance = h2_detail::attr_u64(*c, "findings_performance");
193	        e.findings.portability = h2_detail::attr_u64(*c, "findings_portability");
194	        a.entries.push_back(std::move(e));
195	    }
196	    return a;
197	}
