199	/// h2_score_for — der honest-n/a-Resolver des Treibers: Score eines SOTA-Lebewesens fuer die
200	/// CSV-Endspalte h2_code_quality_score. Fuer die 6 SOTA ist der Profil-Lebewesen-Name identisch
201	/// zum sota-Profil-Dateistamm (art/hot/masstree/surf/start/wormhole); prt_art (Prüfling, KEIN
202	/// Original-Quell-Repository) hat bewusst KEINEN Akten-Eintrag. Fehlende Akte, fehlender Eintrag
203	/// oder leerer Score ⇒ "n/a" — NIE 0, NIE ein erfundener Wert.
204	[[nodiscard]] inline std::string h2_score_for(std::optional<H2ScoreAkte> const& akte, std::string const& lebewesen) {
205	    if (!akte.has_value()) return "n/a";
206	    H2CodeQualityEntry const* e = akte->entry(lebewesen);
207	    if (e == nullptr || e->score.empty()) return "n/a";
208	    return e->score;
209	}
